
extern int sqlite3_busy_timeout(sqlite3*,int);
static volatile int entered=0,okay=0;static const char *dbpath;static int use_step;
static void *writer(void *unused){char bottom;ep_gc_register_thread(&bottom);sqlite3 *db=0;sqlite3_open(dbpath,&db);sqlite3_busy_timeout(db,10000);long long preserved=ptr_to_str((long long)"retained across SQLite lock wait");ep_gc_push_root(&preserved);long long stmt=0;if(use_step)stmt=ep_sqlite3_prepare_v2((long long)db,(long long)"BEGIN IMMEDIATE");entered=1;long long result=use_step?ep_sqlite3_step(stmt):ep_sqlite3_exec((long long)db,(long long)"BEGIN IMMEDIATE",0,0,0);okay=(result==(use_step?101:0))&&strcmp((char*)preserved,"retained across SQLite lock wait")==0;if(stmt)ep_sqlite3_finalize(stmt);sqlite3_exec(db,"COMMIT",0,0,0);sqlite3_close(db);ep_gc_pop_roots(1);ep_gc_unregister_thread();return 0;}
int main(int argc,char **argv){init_ep_args(argc,argv);__ep_init_constants();dbpath=argv[1];use_step=atoi(argv[2]);sqlite3 *db=0;sqlite3_open(dbpath,&db);sqlite3_exec(db,"CREATE TABLE IF NOT EXISTS t(n);BEGIN IMMEDIATE",0,0,0);pthread_t thread;pthread_create(&thread,0,writer,0);while(!entered)usleep(1000);usleep(20000);long long start=ep_time_now_ms();for(int i=0;i<50;i++){EP_GC_UPDATE_TOP();pthread_mutex_lock(&ep_gc_mutex);ep_gc_stop_the_world();ep_gc_collect_major();ep_gc_start_the_world();pthread_mutex_unlock(&ep_gc_mutex);}long long ms=ep_time_now_ms()-start;sqlite3_exec(db,"COMMIT",0,0,0);pthread_join(thread,0);long long rows=create_list();ep_gc_push_root(&rows);int cb=ep_sqlite3_exec((long long)db,(long long)"WITH RECURSIVE n(x) AS(SELECT 1 UNION ALL SELECT x+1 FROM n WHERE x<1000) SELECT x FROM n",(long long)sqlite_list_callback,rows,0);int n=length_list(rows);ep_gc_pop_roots(1);printf("{\"milliseconds\":%lld,\"writer_and_roots_ok\":%d,\"parked_after\":%d,\"callback_result\":%d,\"callback_rows\":%d}\n",ms,okay,ep_gc_parked_count,cb,n);sqlite3_close(db);return !(okay&&ep_gc_parked_count==0&&cb==0&&n==1000);}
